create or replace function public."P132_EnsureLearnerProfile"() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare u uuid:=auth.uid(); p public."TblP132LearnerProfile"; begin if u is null then raise exception 'Authentication required'; end if; insert into public."TblP132LearnerProfile"("UserID") values(u) on conflict("UserID") do nothing; select * into p from public."TblP132LearnerProfile" where "UserID"=u; return jsonb_build_object('user_id',p."UserID",'target_language',p."TargetLanguage"); end $$;
create or replace function public."P132_SetTargetLanguage"(p_language text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_language not in('en','ja') then raise exception 'Unsupported language'; end if; update public."TblP132LearnerProfile" set "TargetLanguage"=p_language,"UpdatedAt"=now() where "UserID"=auth.uid(); end $$;
create or replace function public."P132_GetReadingFeed"(p_limit integer default 20) returns table(article_id bigint,title text,summary text,published_at timestamptz,category text) language sql security definer set search_path=public,pg_temp as $$ select a."ArticleID",a."Title",a."Summary",a."PublishedAt",a."Category" from public."TblP132Article" a where auth.uid() is not null and a."IsPublished" order by a."PublishedAt" desc nulls last,a."ArticleID" desc limit least(greatest(p_limit,1),50) $$;
create or replace function public."P132_RecalculateVocabularyState"(p_user uuid,p_concept bigint,p_language text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare e int;t int;u int;s numeric;stage text;le timestamptz;lt timestamptz;lu timestamptz; begin select count(*),max("DisplayedAt") into e,le from public."TblP132Exposure" where "UserID"=p_user and "ConceptID"=p_concept and "TargetLanguage"=p_language; select count(*) filter(where v."EvidenceType"='translation_request'),count(*) filter(where v."EvidenceType"='understand'),max(v."OccurredAt") filter(where v."EvidenceType"='translation_request'),max(v."OccurredAt") filter(where v."EvidenceType"='understand') into t,u,lt,lu from public."TblP132LearnerEvidence" v join public."TblP132Exposure" x on x."ExposureID"=v."ExposureID" where x."UserID"=p_user and x."ConceptID"=p_concept and x."TargetLanguage"=p_language; s:=greatest(0,least(100,(e*3)+(u*12)-(t*18))); stage:=case when e=0 then 'new' when s>=60 and e>=5 then 'stable' when s>=30 and e>=3 then 'familiar' else 'emerging' end; insert into public."TblP132LearnerVocabularyState"("UserID","ConceptID","TargetLanguage","ExposureCount","TranslationRequestCount","UnderstandCount","FamiliarityScore","FamiliarityStage","LastExposedAt","LastTranslationAt","LastUnderstandAt","UpdatedAt") values(p_user,p_concept,p_language,e,t,u,s,stage,le,lt,lu,now()) on conflict("UserID","ConceptID","TargetLanguage") do update set "ExposureCount"=excluded."ExposureCount","TranslationRequestCount"=excluded."TranslationRequestCount","UnderstandCount"=excluded."UnderstandCount","FamiliarityScore"=excluded."FamiliarityScore","FamiliarityStage"=excluded."FamiliarityStage","LastExposedAt"=excluded."LastExposedAt","LastTranslationAt"=excluded."LastTranslationAt","LastUnderstandAt"=excluded."LastUnderstandAt","UpdatedAt"=now(); end $$;
create or replace function public."P132_PrepareArticle"(p_article_id bigint) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid();lang text;art public."TblP132Article";budget int;cnt int:=0;cur int:=0;r record;segments jsonb:='[]'::jsonb;displaytext text;eid bigint; begin if uid is null then raise exception 'Authentication required';end if; perform public."P132_EnsureLearnerProfile"();select "TargetLanguage" into lang from public."TblP132LearnerProfile" where "UserID"=uid;select * into art from public."TblP132Article" where "ArticleID"=p_article_id and "IsPublished";if not found then raise exception 'Article not found';end if;budget:=least(10,greatest(1,ceil(length(coalesce(art."ContentText",art."Summary",''))::numeric/100.0*2)::int)); if not exists(select 1 from public."TblP132Exposure" where "UserID"=uid) then budget:=greatest(1,ceil(budget/2.0)::int);end if; for r in select o.*,f."FormID",f."SurfaceForm",f."Reading",coalesce(s."FamiliarityStage",'new') stage,case coalesce(s."FamiliarityStage",'new') when 'emerging' then 4 when 'stable' then 4 when 'familiar' then 3 else 1 end priority from public."TblP132ArticleOccurrence" o join public."TblP132VocabularyConcept" c on c."ConceptID"=o."ConceptID" and c."IsActive" and c."ReviewStatus"='approved' join lateral(select * from public."TblP132VocabularyForm" f where f."ConceptID"=o."ConceptID" and f."LanguageCode"=lang and f."IsActive" order by f."IsPreferred" desc,f."FormID" limit 1) f on true left join public."TblP132LearnerVocabularyState" s on s."UserID"=uid and s."ConceptID"=o."ConceptID" and s."TargetLanguage"=lang where o."ArticleID"=p_article_id and o."ReplacementEligible" order by priority desc,o."MatchConfidence" desc nulls last,o."StartOffset" loop exit when cnt>=budget; if r."StartOffset">=cur then if r."StartOffset">cur then segments:=segments||jsonb_build_array(jsonb_build_object('text',substring(coalesce(art."ContentText",art."Summary",'') from cur+1 for r."StartOffset"-cur)));end if; displaytext:=case when lang='ja' and r."Reading" is not null then r."SurfaceForm"||'（'||r."Reading"||'）' else r."SurfaceForm" end; insert into public."TblP132Exposure"("UserID","ArticleID","OccurrenceID","ConceptID","DisplayedFormID","TargetLanguage","PresentationMode","AlgorithmVersion","InfiltrationRate") values(uid,p_article_id,r."OccurrenceID",r."ConceptID",r."FormID",lang,case when lang='ja' and r."Reading" is not null then 'surface_reading' else 'surface' end,'P132-ALG-0.1',budget::numeric/greatest(length(coalesce(art."ContentText",art."Summary",'')),1)) returning "ExposureID" into eid; segments:=segments||jsonb_build_array(jsonb_build_object('text',r."OriginalText",'display_text',displaytext,'exposure_id',eid));perform public."P132_RecalculateVocabularyState"(uid,r."ConceptID",lang);cur:=r."EndOffset";cnt:=cnt+1;end if; end loop; if cur<length(coalesce(art."ContentText",art."Summary",'')) then segments:=segments||jsonb_build_array(jsonb_build_object('text',substring(coalesce(art."ContentText",art."Summary",'') from cur+1)));end if; return jsonb_build_object('article_id',art."ArticleID",'title',art."Title",'original_url',art."OriginalURL",'target_language',lang,'algorithm_version','P132-ALG-0.1','segments',segments);end $$;
create or replace function public."P132_RequestTranslation"(p_exposure_id bigint) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare x public."TblP132Exposure";m text;begin select * into x from public."TblP132Exposure" where "ExposureID"=p_exposure_id and "UserID"=auth.uid();if not found then raise exception 'Exposure not found';end if;insert into public."TblP132LearnerEvidence"("ExposureID","EvidenceType") values(p_exposure_id,'translation_request') on conflict do nothing;select "MeaningZh" into m from public."TblP132VocabularyConcept" where "ConceptID"=x."ConceptID";perform public."P132_RecalculateVocabularyState"(x."UserID",x."ConceptID",x."TargetLanguage");return jsonb_build_object('meaning_zh',m);end $$;
create or replace function public."P132_ReportUnderstand"(p_exposure_id bigint) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare x public."TblP132Exposure";begin select * into x from public."TblP132Exposure" where "ExposureID"=p_exposure_id and "UserID"=auth.uid();if not found then raise exception 'Exposure not found';end if;insert into public."TblP132LearnerEvidence"("ExposureID","EvidenceType") values(p_exposure_id,'understand') on conflict do nothing;perform public."P132_RecalculateVocabularyState"(x."UserID",x."ConceptID",x."TargetLanguage");end $$;
